-- Assessment requests and their input manifests (SCOPE-001, CONTEXT_PACK §7, §8.3, §8.6, §8.7). Generated by
-- `pnpm db:generate` from src/schema/scope.ts, then reviewed. Forward-only: never edit once applied; add a new migration.
-- `max_intrusiveness` never admits `destructive` (CHECK). Credential refs are references only, never plaintext.
-- The composite FK from input_manifests names `assessment_request_id` alone in its ON DELETE SET NULL column list
-- (PostgreSQL 15+): a deleted request leaves its manifest in place, unlinked, so evidence is kept. The app role gets
-- no DELETE on either table; a request ends as `withdrawn` or `rejected`, never as a row removal.
CREATE TABLE "assessment_requests" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"public_id" text NOT NULL,
	"mode" text NOT NULL,
	"objective" text NOT NULL,
	"asset_ids" uuid[] NOT NULL,
	"sa_id" uuid,
	"input_manifest_id" uuid,
	"scope_rules" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"max_intrusiveness" text NOT NULL,
	"budgets" jsonb NOT NULL,
	"trigger" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"requested_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"state_version" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "assessment_requests_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "assessment_requests_public_id_check" CHECK (starts_with("assessment_requests"."public_id", 'areq_') AND length("assessment_requests"."public_id") > 5),
	CONSTRAINT "assessment_requests_mode_check" CHECK ("assessment_requests"."mode" IN ('black', 'grey', 'white')),
	CONSTRAINT "assessment_requests_objective_check" CHECK (length("assessment_requests"."objective") >= 1),
	CONSTRAINT "assessment_requests_max_intrusiveness_check" CHECK ("assessment_requests"."max_intrusiveness" <> 'destructive' AND "assessment_requests"."max_intrusiveness" IN ('passive', 'active_safe', 'state_changing')),
	CONSTRAINT "assessment_requests_budgets_object_check" CHECK (jsonb_typeof("assessment_requests"."budgets") = 'object'),
	CONSTRAINT "assessment_requests_scope_rules_object_check" CHECK (jsonb_typeof("assessment_requests"."scope_rules") = 'object'),
	CONSTRAINT "assessment_requests_trigger_check" CHECK ("assessment_requests"."trigger" IN ('console', 'api', 'ci', 'schedule', 'retest')),
	CONSTRAINT "assessment_requests_status_check" CHECK ("assessment_requests"."status" IN ('draft', 'submitted', 'withdrawn', 'promoted', 'rejected')),
	CONSTRAINT "assessment_requests_submitted_check" CHECK ("assessment_requests"."status" NOT IN ('submitted', 'promoted', 'rejected') OR ("assessment_requests"."sa_id" IS NOT NULL AND cardinality("assessment_requests"."asset_ids") >= 1))
);
